from .base import EMSSInterface
import time


class eNBManager(EMSSInterface):
    """
    EMSsim keywords related to eNB management
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(eNBManager, self).__init__()

    def software_version_should_be(self, version, type="Active", enb_id=None, bts_id=None, alias=None):
        """
        Verifies if current eNB software version equals to the given version.

        :param version: software version to compare with (string)
        :param type: type of partition, can be 'Active' (default) or 'Passive'
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------+------------------------------+---------------+
        |                              Examples                                     |
        +============================+==============================+===============+
        | software version should be | FL17_FSM3_9999_161122_034217 |               |
        +----------------------------+------------------------------+---------------+
        | software version should be | FL17_FSM3_9999_161031_033736 | type= Passive |
        +----------------------------+------------------------------+---------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(type == "Active" or type == "Passive", "Wrong parameters! type should be 'Active' or 'Passive'")
        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        sw_ver = self._get_emssim().cmd_sw_version()
        self._assert(sw_ver.run(), "Software version request procedure failed")
        ret = sw_ver.returned_data()
        self._assert(ret['build_table'][type]['BUILD ID'] == version, "%s versions doesn't match! eNB's software version is %s" %
                     (type, ret['build_table'][type]['BUILD ID']))

    def reset_enb_and_wait_for_recovery(self, recovery_timeout=1200, delay=30, retry_sleep=30, enb_id=None, bts_id=None, alias=None):
        """
        Resets eNB and waits until eNB state will be onAir.

        :param recovery_timeout: timeout for operation in seconds (default 1200)
        :param delay: see delay in wait_for_enb_on_air
        :param retry_sleep: see retry_sleep in wait_for_enb_on_air
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------------+-----------------------+
        |                          Examples                        |
        +==================================+=======================+
        | reset enb and wait for discovery | recovery_timeout= 600 |
        +----------------------------------+-----------------------+
        """
        recovery_timeout = self._opt_int(recovery_timeout)
        delay = self._opt_int(delay)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        self._assert(self._get_emssim().cmd_reset().run(), "Reset operation failed")
        time.sleep(delay)
        self.wait_for_enb_on_air(recovery_timeout, delay=delay, retry_sleep=retry_sleep)

    def reset_enb(self, enb_id=None, bts_id=None, alias=None):
        """
        Resets BTS, do not wait for getting up.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------+
        |  Examples  |
        +============+
        | Reset enb  |
        +------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        self._assert(self._get_emssim().cmd_reset().run(), "Reset operation failed")

    def perform_software_update(self, target, delay_after=30, enb_id=None, bts_id=None, alias=None):
        """
        Performs a software update with activation.

        :param target: Path to either the TargetBD xml file (unpacked version) or load package zip file (packed version).
        :param delay_after: sleep in seconds after software update completed (default 30)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+-----------------------------------------------------------------------------------------------------------------------+
        |                                                  Examples                                                                               |
        +=================+=======================================================================================================================+
        | software update | /home/emssim/LOADS/FL00_FSM3_9999_161128_034323/FL00_FSM3_9999_161128_034323_release_BTSSM_downloadable_wo_images.zip |
        +-----------------+-----------------------------------------------------------------------------------------------------------------------+
        | software update | /home/emssim/LOADS/TargetBD_FL00_FSM3_9999_161128_034323.xml                                                          |
        +-----------------+-----------------------------------------------------------------------------------------------------------------------+
        """
        delay_after = self._opt_int(delay_after)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        self._clear_cache()
        self._assert(self._get_emssim().cmd_sw_update().run(target), "Software update operation failed")
        time.sleep(delay_after)

    def perform_auto_config_command(self, *args, **kwargs):
        """
        Sets preferences for eNodeB auto configuration. \
        See 'help auto_config' in EMSsim session for full list of parameters.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = kwargs.pop('bts_id', None)
        enb_id = kwargs.pop('enb_id', None)
        alias = kwargs.pop('alias', None)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        auto_config_command = self._get_emssim().cmd_auto_config()
        self._assert(auto_config_command.run(*args, **kwargs), "Auto Config command execution failed")
        return auto_config_command.returned_data()

    def perform_auto_sw_update(self, *args, **kwargs):
        """
        Sets preferences for eNodeB originated SW update. \
        See 'help auto_sw_update' in EMSsim session for full list of parameters.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------------+---------------------------------------------------------------------------------------------------------------+
        |                                                 Examples                                                                                |
        +=========================+===============================================================================================================+
        | perform software update | /home/emssim/LOADS/FL00_FSM3_9999_161128_034323_release_BTSSM_downloadable_wo_images.zip                      |
        +-------------------------+---------------------------------------------------------------------------------------------------------------+
        | perform software update | /home/emssim/LOADS/TargetBD_FL00_FSM3_9999_161128_034323.xml                                                  |
        +-------------------------+---------------------------------------------------------------------------------------------------------------+
        """
        bts_id = kwargs.pop('bts_id', None)
        enb_id = kwargs.pop('enb_id', None)
        alias = kwargs.pop('alias', None)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._clear_cache()
        auto_sw_update_cmd = self._get_emssim().cmd_auto_sw_update()
        auto_sw_update_cmd.run(*args, **kwargs)
        return auto_sw_update_cmd.returned_data()

    def wait_for_enb_discovery(self, timeout=360, delay=30, silent=False, retry_sleep=120, enb_id=None, bts_id=None, alias=None):
        """
        Waits until eNB is discovered.

        :param timeout: maximum waiting period in seconds (default: 360 = 3 * retry_sleep)
        :param delay: delay to first check in seconds (default: 30)
        :param silent: if True then do not assert if BTS not discovered after timeout (default: False)
        :param retry_sleep: sleep between verifications in seconds (default: 120 = Registration + StartSession timeout)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------------+-----+
        |          Examples            |
        +========================+=====+
        | Wait for enb discovery | 300 |
        +------------------------+-----+
        """
        timeout = self._opt_int(timeout)
        delay = self._opt_int(delay)
        silent = self._opt_bool(silent)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        discovered = False
        time.sleep(delay)
        start_time = time.time()
        while time.time() - start_time < timeout:
            if self._is_bts_connected() and self._has_discover_succeeded():
                discovered = True
                break
            self._run_setup_emss()
            time.sleep(retry_sleep)
        if not silent:
            self._assert(discovered, "Timeout expired! eNB hasn't discovered by %d seconds" % timeout)

    def wait_for_enb_on_air(self, timeout=300, locked_cells=False, disabled_cells=False, delay=30, retry_sleep=30,
                            enb_id=None, bts_id=None, alias=None):
        """
        Waits until eNB state will be onAir.

        :param timeout: maximum waiting time in seconds (default: 300).
        :param locked_cells: True if any cell would be locked (default: False)
        :param disabled_cells: True if any cell would be disabled (default: False)
        :param delay: delay to first check in seconds (default: 30)
        :param retry_sleep: sleep between state verifications in seconds (default: 30)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+-----+
        |          Examples         |
        +=====================+=====+
        | Wait For Enb On Air | 300 |
        +---------------------+-----+
        """
        timeout = self._opt_int(timeout)
        locked_cells = self._opt_bool(locked_cells)
        disabled_cells = self._opt_bool(disabled_cells)
        delay = self._opt_int(delay)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if timeout <= delay:
            timeout = delay + 5
            print("WARNING: timeout cannot be smaller than delay. Increasing value to: %d" % timeout)
        start_time = time.time()
        on_air_flag = False
        all_cells_enabled_or_locked = False
        all_cells_enabled = False
        time.sleep(delay)
        while time.time() - start_time < timeout:
            if self._is_bts_connected() and self._has_discover_succeeded() and self._is_bts_onAir():
                on_air_flag = True
                if disabled_cells:
                    break
                if locked_cells and self._are_all_cells_enabled_or_locked():
                    all_cells_enabled_or_locked = True
                    break
                if self._are_all_cells_enabled():
                    all_cells_enabled = True
                    break
            time.sleep(retry_sleep)
        self._assert(on_air_flag, "Timeout expired! eNB hasn't recovered to state onAir by %d seconds" % timeout)
        self._check_cells_conditions(locked_cells, disabled_cells, all_cells_enabled_or_locked, all_cells_enabled, timeout)

    def _check_cells_conditions(self, locked_cells, disabled_cells, all_cells_enabled_or_locked, all_cells_enabled, timeout):
        if disabled_cells:
            return
        if locked_cells:
            self._assert(all_cells_enabled_or_locked, "Not all cells are enabled or locked after %d seconds" % timeout)
            return
        self._assert(all_cells_enabled, "Not all cells are enabled after %d seconds" % timeout)

    def _are_all_cells_enabled(self):
        all_lte_cells = self.get_existing_objects_of_given_type("LNCEL", silent=True)
        all_nr_cells = self.get_existing_objects_of_given_type("NRCELL", silent=True)
        ls = self._get_emssim().cmd_ls()
        ls.run()
        obj_tab = ls.returned_data()['object_table']
        for lte_cell in all_lte_cells:
            if lte_cell in obj_tab:
                if obj_tab[lte_cell]["OPERATIONAL"] != "enabled":
                    print("LTE cell {} is not enabled".format(lte_cell))
                    return False
            else:
                print("Cannot verify if LTE cell {} is enabled".format(lte_cell))
                return False
        for nr_cell in all_nr_cells:
            if nr_cell in obj_tab:
                if obj_tab[nr_cell]["OPERATIONAL"] != "enabled":
                    print("NR cell {} is not enabled".format(nr_cell))
                    return False
            else:
                print("Cannot verify if NR cell {} is enabled".format(nr_cell))
                return False

        print("All cells are enabled: LTE={}, NR={}".format(all_lte_cells, all_nr_cells))
        return True

    def _are_all_cells_enabled_or_locked(self):
        all_lte_cells = self.get_existing_objects_of_given_type("LNCEL", silent=True)
        all_nr_cells = self.get_existing_objects_of_given_type("NRCELL", silent=True)
        ls = self._get_emssim().cmd_ls()
        ls.run()
        obj_tab = ls.returned_data()['object_table']
        for lte_cell in all_lte_cells:
            if lte_cell in obj_tab:
                if obj_tab[lte_cell]["OPERATIONAL"] != "enabled" or obj_tab[lte_cell]["ADMINISTRATIVE"] != "locked":
                    print("LTE cell {} is not enabled or locked".format(lte_cell))
                    return False
            else:
                print("Cannot verify if LTE cell {} is enabled or locked".format(lte_cell))
                return False
        for nr_cell in all_nr_cells:
            if nr_cell in obj_tab:
                if obj_tab[nr_cell]["OPERATIONAL"] != "enabled" or obj_tab[nr_cell]["ADMINISTRATIVE"] != "locked":
                    print("NR cell {} is not enabled or locked".format(nr_cell))
                    return False
            else:
                print("Cannot verify if NR cell {} is enabled or locked".format(nr_cell))
                return False

        print("All cells are enabled or locked: LTE={}, NR={}".format(all_lte_cells, all_nr_cells))
        return True

    def _is_bts_connected(self):
        ret = False
        try:
            bts_conn = self._get_emssim().cmd_bts_connection_status()
            bts_conn.run()
            ret = bts_conn.returned_data()['connection_status']
        except Exception:
            pass
        return ret

    def _has_discover_succeeded(self):
        return self._get_emssim().cmd_discover().run()

    def _is_bts_onAir(self):
        ls = self._get_emssim().cmd_ls()
        ls.run()
        obj_tab = ls.returned_data()['object_table']
        lnbts_name = self.get_LNBTS_object_name(silent=True)
        if lnbts_name is None:
            print("Cannot verify if BTS is onAir: Missing LNBTS/NRBTS object.")
            return False
        if lnbts_name in obj_tab:
            if obj_tab[lnbts_name]["OPERATIONAL"] != "onAir":
                print("%s is not onAir" % lnbts_name)
                return False
        else:
            print("Cannot verify if BTS {} is onAir".format(lnbts_name))
            return False
        print("{} is onAir".format(lnbts_name))
        return True
